USE DATABASE MINOR_PROJECT;

USE SCHEMA CLEAN;

MINOR_PROJECT.CLEAN.CUSTOMER_SHOPPING_BEHAVIOR


-- Use the CLEAN schema
USE DATABASE MINOR_PROJECT;
USE SCHEMA CLEAN;

-- Check the cleaned business table
SELECT *
FROM CUSTOMER_SHOPPING_BEHAVIOR
LIMIT 5;


-- 1. Revenue Analysis
-- Compare total revenue generated by male and female customers.

SELECT
    GENDER,
    SUM(PURCHASE_AMOUNT) AS REVENUE
FROM CUSTOMER_SHOPPING_BEHAVIOR
GROUP BY GENDER;


-- 2. Discount & Spending Analysis
-- Identify discount users whose purchase amounts are at or above
-- the overall average purchase amount.

SELECT
    CUSTOMER_ID,
    PURCHASE_AMOUNT
FROM CUSTOMER_SHOPPING_BEHAVIOR
WHERE DISCOUNT_APPLIED = 'Yes'
  AND PURCHASE_AMOUNT >= (
      SELECT AVG(PURCHASE_AMOUNT)
      FROM CUSTOMER_SHOPPING_BEHAVIOR
  );


-- 3. Product Rating Analysis
-- Rank the top 5 products by average review rating.

SELECT
    ITEM_PURCHASED,
    ROUND(AVG(REVIEW_RATING), 2)
        AS AVERAGE_PRODUCT_RATING
FROM CUSTOMER_SHOPPING_BEHAVIOR
GROUP BY ITEM_PURCHASED
ORDER BY AVERAGE_PRODUCT_RATING DESC
LIMIT 5;


-- 4. Shipping Analysis
-- Compare average purchase amounts for Standard and Express shipping.

SELECT
    SHIPPING_TYPE,
    ROUND(AVG(PURCHASE_AMOUNT), 2) AS AVG_PURCHASE_AMOUNT
FROM CUSTOMER_SHOPPING_BEHAVIOR
WHERE SHIPPING_TYPE IN ('Standard', 'Express')
GROUP BY SHIPPING_TYPE;


-- 5. Subscription Analysis
-- Compare customer counts, average spending and total revenue
-- between subscribers and non-subscribers.

SELECT
    SUBSCRIPTION_STATUS,
    COUNT(CUSTOMER_ID) AS TOTAL_CUSTOMERS,
    ROUND(AVG(PURCHASE_AMOUNT), 2) AS AVG_SPEND,
    ROUND(SUM(PURCHASE_AMOUNT), 2) AS TOTAL_REVENUE
FROM CUSTOMER_SHOPPING_BEHAVIOR
GROUP BY SUBSCRIPTION_STATUS
ORDER BY TOTAL_REVENUE DESC, AVG_SPEND DESC;


-- 6. Discount Dependency Analysis
-- Identify the top 5 products by percentage of purchases
-- with discounts applied.

SELECT
    ITEM_PURCHASED,
    ROUND(
        100.0 * SUM(
            CASE
                WHEN DISCOUNT_APPLIED = 'Yes' THEN 1
                ELSE 0
            END
        ) / NULLIF(COUNT(*), 0),
        2
    ) AS DISCOUNT_RATE
FROM CUSTOMER_SHOPPING_BEHAVIOR
GROUP BY ITEM_PURCHASED
ORDER BY DISCOUNT_RATE DESC
LIMIT 5;


-- 7. Customer Segmentation
-- Classify customers into New, Returning and Loyal segments.

WITH CUSTOMER_TYPE AS (
    SELECT
        CUSTOMER_ID,
        PREVIOUS_PURCHASES,
        CASE
            WHEN PREVIOUS_PURCHASES = 1 THEN 'New'
            WHEN PREVIOUS_PURCHASES BETWEEN 2 AND 10 THEN 'Returning'
            ELSE 'Loyal'
        END AS CUSTOMER_SEGMENT
    FROM CUSTOMER_SHOPPING_BEHAVIOR
)
SELECT
    CUSTOMER_SEGMENT,
    COUNT(*) AS NUMBER_OF_CUSTOMERS
FROM CUSTOMER_TYPE
GROUP BY CUSTOMER_SEGMENT;


-- 8. Product Popularity Analysis
-- Identify the top 3 most purchased products within each category.

WITH ITEM_COUNTS AS (
    SELECT
        CATEGORY,
        ITEM_PURCHASED,
        COUNT(CUSTOMER_ID) AS TOTAL_ORDERS,
        ROW_NUMBER() OVER (
            PARTITION BY CATEGORY
            ORDER BY COUNT(CUSTOMER_ID) DESC
        ) AS ITEM_RANK
    FROM CUSTOMER_SHOPPING_BEHAVIOR
    GROUP BY CATEGORY, ITEM_PURCHASED
)
SELECT
    ITEM_RANK,
    CATEGORY,
    ITEM_PURCHASED,
    TOTAL_ORDERS
FROM ITEM_COUNTS
WHERE ITEM_RANK <= 3
ORDER BY CATEGORY, ITEM_RANK;


-- 9. Repeat Buyer Analysis
-- Compare subscription status among customers
-- with more than 5 previous purchases.

SELECT
    SUBSCRIPTION_STATUS,
    COUNT(CUSTOMER_ID) AS REPEAT_BUYERS
FROM CUSTOMER_SHOPPING_BEHAVIOR
WHERE PREVIOUS_PURCHASES > 5
GROUP BY SUBSCRIPTION_STATUS;


-- 10. Age Group Revenue Analysis
-- Compare total revenue across customer age groups.

SELECT
    AGE_GROUP,
    SUM(PURCHASE_AMOUNT) AS TOTAL_REVENUE
FROM CUSTOMER_SHOPPING_BEHAVIOR
GROUP BY AGE_GROUP
ORDER BY TOTAL_REVENUE DESC;
